def _descend_list_of__reference(
    that: List["Reference"], recurse: bool
) -> Iterator[Class]:
    """
    Iterate over the instances held by :paramref:`that`.

    If :paramref:`recurse` is set, descend recursively into the instances
    as well.
    """
    if not recurse:
        yield from that
        return

    for item in that:
        yield item

        yield from item.descend()


